class Solution {
    public int searchInsert(int[] nums, int target) {
        int possibleIndex = 0;
        for(int i = 0 ; i < nums.length; i++){
            if(nums[i] == target)
                return i;
            else if(nums[i] < target)
                possibleIndex = i+1;
            else if(nums[i] > target)
                break;
        }
        return possibleIndex;
    }
}

